import { Data, paymentCredentialOf, Lucid, Blockfrost, validatorToAddress } from "@lucid-evolution/lucid";
import { getLucid } from "./config";
import { RegistryDatum, RegistryDatumType } from "./utils";

async function main() {
    const lucid = await getLucid();

    const seed = process.env.ADMIN_SEED;
    if (!seed) throw new Error("Missing ADMIN_SEED");


    lucid.selectWallet.fromSeed(seed);

    const adminAddress = await lucid.wallet().address();
    const adminPkh = paymentCredentialOf(adminAddress).hash;

    console.log("Admin address:", adminAddress);
    console.log("Admin PKH:", adminPkh);

    const registryScript = {
        type: "PlutusV3",
        script: "",
    } as const;

    const registryAddress = validatorToAddress("Preprod", registryScript);



    const datumData: RegistryDatumType = {
        admin: adminPkh,
        issuers: [],
        version: 1n,
    };

    const datum = Data.to(datumData as any, RegistryDatum);

    const tx = await lucid
        .newTx()
        .pay.ToContract(
            registryAddress,
            { kind: "inline", value: datum },
            { lovelace: 3_000_000n }
        )
        .complete();

    const signedTx = await tx.sign.withWallet().complete();
    const txHash = await signedTx.submit();

    console.log("Registry initialized:", txHash);
}

main();